{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-WNn3uy/src/lcs.js","content":"/**
 * Longest common subsequence matching between a base document and one side,
 * comparing whole lines as exact strings. Ties in subsequence length are
 * broken so that matches come as early as possible: walking both documents
 * from the start, a match is taken whenever the current lines are equal,
 * and otherwise the side whose remaining subsequence is at least as long as
 * the other's is advanced, preferring to advance the base when they tie.
 */

/**
 * @param {string[]} base
 * @param {string[]} side
 * @returns {[number, number][]} pairs of matched indices, `[baseIndex,
 *   sideIndex]`, in increasing order
 */
export function computeMatches(base, side) {
  const m = base.length
  const n = side.length

  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Int32Array(n + 1)

  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < m && j < n) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Turns a match list into the runs of base lines a side's changes replace.
 * Each change is a stretch the subsequence does not cover: a run of base
 * lines `[baseStart, baseEnd)` replaced by a run of the side's lines
 * `[sideStart, sideEnd)`. An insertion has an empty base run and a deletion
 * an empty side run.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @param {[number, number][]} matches
 * @returns {{baseStart: number, baseEnd: number, sideStart: number, sideEnd: number}[]}
 */
export function computeChanges(base, side, matches) {
  const changes = []
  let baseCursor = 0
  let sideCursor = 0

  for (const [i, j] of matches) {
    if (i > baseCursor || j > sideCursor) {
      changes.push({ baseStart: baseCursor, baseEnd: i, sideStart: sideCursor, sideEnd: j })
    }
    baseCursor = i + 1
    sideCursor = j + 1
  }

  if (baseCursor < base.length || sideCursor < side.length) {
    changes.push({ baseStart: baseCursor, baseEnd: base.length, sideStart: sideCursor, sideEnd: side.length })
  }

  return changes
}
"}

