 * Runs a side's replacement across a region: the lines from the smallest
 * start of its own changes, moved back by however far the region begins
 * before those changes do in the base, to the largest end of its own
 * changes, moved forward by however far the region ends after them. A side
 * untouched anywhere in the region keeps the base's lines for it.
 *
 * @param {{baseStart: number, baseEnd: number}} region
 * @param {{baseStart: number, baseEnd: number, sideStart: number, sideEnd: number}[]} members
 * @param {string[]} doc
 * @param {string[]} base
 * @returns {string[]}
 */
function sideLines(region, members, doc, base) {
  if (members.length === 0) return base.slice(region.baseStart, region.baseEnd)
  const first = members[0]
  const last = members[members.length - 1]
  const frontExtension = first.baseStart - region.baseStart
  const backExtension = region.baseEnd - last.baseEnd
  return doc.slice(first.sideStart - frontExtension, last.sideEnd + backExtension)
}

