 * Splits the base into the stable stretches and merge regions described by
 * the two sides' changes, in base order.
 *
 * Each element is one of:
 *  - `{ type: 'stable', lines }` — a stretch of base lines the merge keeps
 *  - `{ type: 'mine' | 'theirs' | 'both', lines }` — a region that resolved
 *    cleanly
 *  - `{ type: 'conflict', mine, base, theirs }` — a region neither side's
 *    lines nor the base's lines could settle
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {object[]}
 */
export function buildSegments(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine, computeMatches(base, mine)).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs, computeMatches(base, theirs)).map(c => ({ ...c, side: 'theirs' }))

  const allChanges = mineChanges.concat(theirsChanges).sort((a, b) => a.baseStart - b.baseStart)

  const regions = []
  let idx = 0
  while (idx < allChanges.length) {
    const members = [allChanges[idx]]
    let regionStart = allChanges[idx].baseStart
    let regionEnd = allChanges[idx].baseEnd
    idx++
    while (idx < allChanges.length && allChanges[idx].baseStart <= regionEnd) {
      regionEnd = Math.max(regionEnd, allChanges[idx].baseEnd)
      members.push(allChanges[idx])
      idx++
    }
    regions.push({ baseStart: regionStart, baseEnd: regionEnd, members })
  }

