  const [mine, base, theirs] = parts
  const segments = buildSegments(mine, base, theirs)

  const out = []
  let conflicted = false

  for (const segment of segments) {
    if (segment.type === 'conflict') conflicted = true

    if (mode === 'regions') {
      out.push(formatRegionLine(segment))
    } else {
      formatMergeLines(segment, mode === 'merge', out)
    }
  }

  process.stdout.write(out.length === 0 ? '' : `${out.join('\n')}\n`)
  process.exit(conflicted ? 1 : 0)
